public bool TryFormat(Span<char> destination, out int charsWritten,
    ReadOnlySpan<char> format = default, IFormatProvider? provider = null)
{
    provider ??= CultureInfo.CurrentCulture;
    double value = LargestWholeNumberValue;
    string symbol = LargestWholeNumberSymbol;

    // Format number into the span, then append symbol
    if (!value.TryFormat(destination, out charsWritten, format.IsEmpty ? "0.##" : format, provider))
        return false;

    if (destination.Length - charsWritten < symbol.Length + 1)
    { charsWritten = 0; return false; }

    destination[charsWritten++] = ' ';
    symbol.AsSpan().CopyTo(destination[charsWritten..]);
    charsWritten += symbol.Length;
    return true;
}

public override string ToString()
{
    Span<char> buffer = stackalloc char[32];
    if (TryFormat(buffer, out int written))
        return buffer[..written].ToString(); // single allocation
    return $"{LargestWholeNumberValue:0.##} {LargestWholeNumberSymbol}";
}
